/**
 * Load curated UbuWeb link catalog (titles + URLs only, no media).
 * Generated by: npm run build:ubu-catalog
 */

import { readFileSync, existsSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const JSON_PATH = resolve(__dirname, 'ubu-archive-catalog.json')

export function buildUbuCatalog() {
  if (!existsSync(JSON_PATH)) {
    throw new Error(
      `Missing ${JSON_PATH}. Run: npm run build:ubu-catalog`
    )
  }
  const data = JSON.parse(readFileSync(JSON_PATH, 'utf8'))
  if (!Array.isArray(data.entries) || data.entries.length === 0) {
    throw new Error('ubu-archive-catalog.json has no entries')
  }
  return data.entries
}
